const E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(x,d=2)=>Number(x).toLocaleString('en',{maximumFractionDigits:d,minimumFractionDigits:0});
const green='#659351',blue='#4d83be',purple='#8864c2',orange='#ca8d61';
const slider=(id,label,min,max,step,value,unit='')=>({id,label,min,max,step,value,unit});
const select=(id,label,options,value)=>({id,label,options,value});
export function consumption(p){const R=1+p.r/100,beta=1/(1+p.rho/100),available=R*p.a+p.y1,W=available+p.y2/R;let c1=W/(1+beta),bound=false;if(p.constraint==='yes'&&c1>available){c1=available;bound=true}const a1=available-c1,c2=R*a1+p.y2,s=a1-p.a;return{R,beta,W,c1,c2,a1,s,bound,available};}
export function worker(p){const R=1+p.r/100,beta=1/(1+p.rho/100),W=p.h*(p.w1+p.w2/R),eta=p.eta;let c=W/((1+eta)*(1+beta));let l1,l2;for(let j=0;j<80;j++){l1=Math.min(p.h,eta*c/p.w1);l2=Math.min(p.h,eta*beta*R*c/p.w2);const excess=c*(1+beta)+p.w1*l1+p.w2*l2/R-W;c-=excess/(1+beta+(l1<p.h?eta:0)+(l2<p.h?eta*beta:0))}l1=Math.min(p.h,eta*c/p.w1);l2=Math.min(p.h,eta*beta*R*c/p.w2);return{c1:c,c2:beta*R*c,l1,l2,n1:p.h-l1,n2:p.h-l2,s:p.w1*(p.h-l1)-c,W};}
export function labourChoice(p,w=p.w){const sigma=p.sigma??1,inc=w*p.h+p.v;let lo=0,hi=p.h;const F=l=>p.eta*Math.max(0,inc-w*l)**sigma-w*l;let l;if(F(hi)>=0)l=hi;else{for(let j=0;j<90;j++){const mid=(lo+hi)/2;if(F(mid)>0)lo=mid;else hi=mid}l=(lo+hi)/2}return{l,n:p.h-l,c:inc-w*l,inc,sigma};}
export function policy(p){const m=p.M/p.P,den=p.k+p.h*p.b;let Y,r;const floorY=(p.a+p.pi)/p.b,floorBalances=p.l0+p.k*floorY,trap=p.regime==='trap'&&m>=floorBalances;if(trap){r=-p.pi;Y=floorY}else if(p.regime==='vertical'){Y=(m-p.l0)/p.k;r=p.a-p.b*Y}else{Y=(m-p.l0+p.h*(p.a+p.pi))/den;r=p.a-p.b*Y}return{Y,r,i:r+p.pi,m,trap,floorBalances};}
function chart({xmin=0,xmax=100,ymin=0,ymax=100,xlabel='x',ylabel='y',curves=[],points=[],lines=[],bars=[]}){const L=54,R=550,T=32,B=290,W=590,H=342;const x=v=>L+(v-xmin)/(xmax-xmin)*(R-L),y=v=>B-(v-ymin)/(ymax-ymin)*(B-T);let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${E(ylabel)} against ${E(xlabel)}"><defs><clipPath id="labclip"><rect x="${L}" y="${T}" width="${R-L}" height="${B-T}"/></clipPath></defs>`;for(let j=0;j<=4;j++){let v=ymin+(ymax-ymin)*j/4;s+=`<path d="M${L} ${y(v)}H${R}" stroke="#e9ede3"/><text x="${L-9}" y="${y(v)+4}" text-anchor="end">${f(v,1)}</text>`;v=xmin+(xmax-xmin)*j/4;s+=`<text x="${x(v)}" y="${B+20}" text-anchor="middle">${f(v,1)}</text>`}s+=`<path d="M${L} ${T}V${B}H${R}" stroke="#a3afa0" fill="none"/><text x="${L}" y="17">${E(ylabel)}</text><text x="${R}" y="${H-8}" text-anchor="end">${E(xlabel)}</text>`;for(const c of curves){let path='',pen=false;for(let j=0;j<=220;j++){const X=xmin+(xmax-xmin)*j/220,Y=c.fn(X);if(!Number.isFinite(Y)){pen=false;continue}path+=`${pen?'L':'M'}${x(X).toFixed(2)},${y(Y).toFixed(2)} `;pen=true}s+=`<path d="${path}" fill="none" stroke="${c.color||green}" stroke-width="${c.dash?1.6:2.7}" ${c.dash?'stroke-dasharray="6 5" opacity=".5"':''} clip-path="url(#labclip)"/>`}for(const line of lines){s+=`<path d="M${x(line.x1)} ${y(line.y1)}L${x(line.x2)} ${y(line.y2)}" stroke="${line.color||orange}" ${line.dash?'stroke-dasharray="5 4"':''} stroke-width="2" clip-path="url(#labclip)"/>`}for(const p of points){if(p.x<xmin||p.x>xmax||p.y<ymin||p.y>ymax)continue;s+=`<path d="M${L} ${y(p.y)}H${x(p.x)}V${B}" fill="none" stroke="#b8c3ae" stroke-dasharray="3 4"/><circle cx="${x(p.x)}" cy="${y(p.y)}" r="5" fill="${p.color||green}" stroke="white" stroke-width="2"/><text x="${Math.min(R-15,x(p.x)+9)}" y="${y(p.y)-10}">${E(p.label||'')}</text>`}return s+'</svg>'}
const metric=(label,value)=>({label,value});
const output=(graph,values,explain,legend=[])=>({graph,values,explain,legend});
export const LABS={
foundations:[{id:'stocks',title:'From a flow to a stock',description:'Change saving, returns and prices. See which quantities actually change.',controls:[slider('a','Initial wealth',0,200,5,80),slider('s','Non-interest surplus',-20,20,1,5),slider('r','Interest rate',0,10,1,3,'%'),slider('P','Price level',.5,2,.1,1)],assumptions:'Constant non-interest income minus consumption, paid at year end, with a fixed interest rate on assets or debt. Total saving includes interest income. The price slider only deflates nominal wealth.',calculate:p=>{const A=t=>p.r===0?p.a+p.s*t:p.a*(1+p.r/100)**t+p.s*((1+p.r/100)**t-1)/(p.r/100);const vals=Array.from({length:11},(_,i)=>A(i)),lo=Math.min(0,...vals,...vals.map(v=>v/p.P)),hi=Math.max(100,...vals,...vals.map(v=>v/p.P))*1.12;return output(chart({xmax:10,ymin:lo,ymax:hi,xlabel:'Years',ylabel:'Wealth',curves:[{fn:A,color:green},{fn:t=>A(t)/p.P,color:blue}]}),[metric('Nominal wealth after 10 years',f(A(10))),metric('Real wealth after 10 years',f(A(10)/p.P)),metric('First-year total saving',f(p.s+p.a*p.r/100))],`The non-interest surplus is ${f(p.s)} per year. Total saving is Sₜ = rAₜ + surplus, so first-year saving is ${f(p.s+p.a*p.r/100)}. Wealth is the accumulated stock, with Aₜ₊₁ = Aₜ + Sₜ. ${p.s+p.a*p.r/100<0?'Negative total saving reduces wealth in the first year.':'Positive total saving raises wealth in the first year.'} A negative non-interest surplus can coexist with positive total saving if interest income is large enough. Higher P reduces real wealth for the same nominal stock; lower P increases it.`,[{label:'Nominal wealth',color:green},{label:'Real wealth',color:blue}])}}],
labour:[{id:'production',title:'Production and marginal product',description:'Move productivity, capital and labour. Separate diminishing MP from returns to scale.',controls:[slider('A','Productivity A',.5,3,.1,1),slider('K','Capital K',20,200,5,100),slider('N','Labour N',10,200,5,100),slider('alpha','Capital share α',.1,.9,.05,.3),select('view','Show',[['output','Production Y'],['mp','Marginal product MPN']],'output')],assumptions:'Y = A K^α N^(1−α), 0 < α < 1. K is held fixed along the plotted curve. Constant returns to scale requires changing both inputs.',calculate:p=>{const Y=n=>p.A*p.K**p.alpha*n**(1-p.alpha),mp=n=>(1-p.alpha)*p.A*p.K**p.alpha*n**(-p.alpha),fun=p.view==='mp'?mp:Y,hi=fun(p.view==='mp'?10:220)*1.2;return output(chart({xmin:10,xmax:220,ymax:hi,xlabel:'Labour N',ylabel:p.view==='mp'?'Marginal product of labour':'Output Y',curves:[{fn:fun,color:green}],points:[{x:p.N,y:fun(p.N),label:'Your choice'}]}),[metric('Output Y',f(Y(p.N))),metric('MPN = real wage at optimum',f(mp(p.N))),metric('Labour share',f((1-p.alpha)*100)+'%')],`MPN is positive but falls as N rises because each worker has less fixed capital. Higher A or K shifts both production and MPN up; lower A or K shifts both down. Doubling N alone multiplies Y by ${f(2**(1-p.alpha))}. Doubling K and N together doubles Y. These are different experiments.`)}},{id:'supply',title:'Income and leisure',description:'Create rising, flat or backward-bending labour supply by changing preference curvature.',controls:[slider('w','Real wage w',.5,8,.1,2),slider('v','Nonlabour income v',0,40,1,0),slider('eta','Leisure weight η',.2,3,.1,1),slider('h','Time endowment h',8,24,1,16),slider('sigma','Consumption curvature σ',.5,2,.25,1),select('view','Graph',[['budget','Budget and optimum'],['supply','Individual labour supply']],'budget')],assumptions:'Illustrative preference family with u_c=c^(−σ), u_l=η/l and c=w(h−l)+v. σ=1 gives log consumption utility. This family illustrates possible wage responses, not a universal labour-supply curve.',calculate:p=>{const v=labourChoice(p),u=c=>v.sigma===1?Math.log(c):c**(1-v.sigma)/(1-v.sigma),U=u(v.c)+p.eta*Math.log(v.l),ic=l=>{if(l<=0)return NaN;const z=U-p.eta*Math.log(l);if(v.sigma===1)return Math.exp(z);const base=(1-v.sigma)*z;return base>0?base**(1/(1-v.sigma)):NaN},nLow=labourChoice(p,Math.max(.01,p.w*.99)).n,nHigh=labourChoice(p,p.w*1.01).n,response=v.n<1e-7?'are masked by a binding no-work limit, which is not evidence of equal income and substitution effects':Math.abs(nHigh-nLow)<1e-7?'exactly cancel locally':nHigh>nLow?'produce an upward-sloping response locally':'produce a backward-bending response locally';const graph=p.view==='supply'?chart({xmin:.5,xmax:8,ymax:p.h,xlabel:'Real wage w',ylabel:'Individual work N',curves:[{fn:w=>labourChoice(p,w).n,color:green}],points:[{x:p.w,y:v.n,label:'Chosen wage'}]}):chart({xmax:p.h,ymax:Math.max(v.inc*1.1,20),xlabel:'Leisure l',ylabel:'Consumption c',curves:[{fn:l=>v.inc-p.w*l,color:blue},{fn:ic,color:green}],points:[{x:v.l,y:v.c,label:v.n===0?'No-work corner':'Optimum'}]});return output(graph,[metric('Work N',f(v.n)),metric('Leisure l',f(v.l)),metric('Consumption c',f(v.c))],`The wage raises the opportunity cost of leisure but also raises earning power. At these settings the effects ${response}. At an interior optimum ηc^σ/l=w. With v=0 and σ=1 the wage effects cancel exactly. With v=0 and σ>1 the income effect dominates and work falls as the wage rises; σ<1 gives the opposite response. Higher nonlabour income shifts the budget out and increases leisure in this preference family. At l=h the zero-work corner changes the equality condition.`,p.view==='budget'?[{label:'Budget',color:blue},{label:'Indifference curve',color:green}]:[{label:'Individual labour supply',color:green}])}},{id:'labour-market',title:'Labour market and potential output',description:'Distinguish a demand shift from a supply shift in a market with upward-sloping aggregate supply.',controls:[slider('A','Productivity A',.5,2,.1,1),slider('K','Capital K',50,150,5,100),slider('s','Supply scale',30,150,5,100)],assumptions:'Cobb–Douglas with α = 0.3 and aggregate supply w = N/s. This maintained aggregate supply schedule is not a universal individual wage response.',calculate:p=>{const N=(.7*p.A*p.K**.3*p.s)**(1/1.3),w=N/p.s,Y=p.A*p.K**.3*N**.7;return output(chart({xmin:5,xmax:200,ymax:3,xlabel:'Employment N',ylabel:'Real wage w',curves:[{fn:n=>.7*p.A*p.K**.3*n**(-.3),color:green},{fn:n=>n/p.s,color:blue}],points:[{x:N,y:w,label:'Market clearing'}]}),[metric('Employment N*',f(N)),metric('Real wage w*',f(w)),metric('Potential output Y*',f(Y))],`Higher productivity or capital shifts labour demand out, raising equilibrium N and w on the assumed supply curve. A larger supply scale shifts labour supply right, raising N but lowering w. Reductions reverse these movements explicitly through lower MPN or fewer willing workers. Potential output follows actual equilibrium N and productive capacity, not an arbitrary output target.`,[{label:'Labour demand',color:green},{label:'Labour supply',color:blue}])}},{id:'unemployment',title:'Who counts as unemployed?',description:'Move people between employment, unemployment and outside the labour force.',controls:[slider('E','Employed',10,80,1,60),slider('U','Unemployed, searching',0,20,1,5),slider('O','Outside labour force',0,50,1,35),slider('ustar','Natural unemployment u*',1,10,.5,5,'%')],assumptions:'Illustrative population counts and Okun coefficient 2. Okun’s law is an empirical approximation, not an identity.',calculate:p=>{const pop=p.E+p.U+p.O,u=100*p.U/(p.E+p.U),part=100*(p.E+p.U)/pop,gap=-2*(u-p.ustar);return output(chart({xmax:Math.max(20,u*1.15),ymin:Math.min(-30,gap-5),ymax:Math.max(20,gap+5),xlabel:'Unemployment rate (%)',ylabel:'Output gap (%)',curves:[{fn:x=>-2*(x-p.ustar),color:green}],points:[{x:u,y:gap,label:'Okun prediction'}]}),[metric('Unemployment rate',f(u)+'%'),metric('Participation rate',f(part)+'%'),metric(gap<=-100?'Invalid extrapolation':'Illustrative output gap',gap<=-100?'Outside model':f(gap)+'%')],`Unemployment uses E + U in its denominator. Participation uses E + U + O. If a discouraged worker moves from U to O, measured unemployment falls even though employment does not rise. Moving from O to U raises participation and can raise unemployment without job losses. At u = u*, cyclical unemployment and the predicted output gap are zero. ${gap<=-100?'This input extrapolates Okun’s approximation to a gap of −100% or worse, implying nonpositive output. That is economically invalid; treat the displayed line as an algebraic extrapolation, not a feasible output forecast.':Math.abs(u-p.ustar)>10?'This is far from the normal range for a local Okun approximation. Its numerical prediction should not be interpreted literally.':''}`)}}],
consumption:[{id:'consumer',title:'Consumption across two periods',description:'Rotate the budget, change resources and test a borrowing constraint.',controls:[slider('y1','Current income y₁',10,200,5,60),slider('y2','Future income y₂',10,200,5,100),slider('a','Initial wealth a₀',0,100,5,0),slider('r','Real interest r',-5,30,1,5,'%'),slider('rho','Impatience ρ',0,30,1,5,'%'),select('constraint','No borrowing',[['no','Unconstrained'],['yes','Cannot borrow']],'no')],assumptions:'u(c)=ln c, β=1/(1+ρ), terminal assets zero, initial a₀ earns interest before current consumption. When borrowing binds, the Euler equality becomes an inequality.',calculate:p=>{const v=consumption(p),max=v.W*1.1;return output(chart({xmax:max,ymax:v.R*v.W*1.1,xlabel:'Current consumption c₁',ylabel:'Future consumption c₂',curves:[...(p.constraint==='yes'?[{fn:c=>v.R*(v.W-c),color:blue,dash:true}]:[]),{fn:c=>p.constraint==='yes'&&c>v.available?NaN:v.R*(v.W-c),color:blue},{fn:c=>c>0?v.c2*(v.c1/c)**(1/v.beta):NaN,color:green}],points:[{x:v.c1,y:v.c2,label:v.bound?'Borrowing constraint':'Optimum'},{x:v.available,y:p.y2,label:'a₁ = 0',color:orange}]}),[metric('Current consumption',f(v.c1)),metric('Future consumption',f(v.c2)),metric('Saving s₁ = a₁ − a₀',f(v.s))],`Lifetime resources in current units are ${f(v.W)}. ${v.bound?'The desired borrowing is infeasible, so c₁ equals available current resources. Future income increases need not raise current consumption at this corner.':`The Euler condition gives c₂/c₁ = β(1+r) = ${f(v.beta*v.R,3)}.`} A rise in current or future income raises unconstrained consumption in both periods. A rise in r changes both relative prices and lifetime resources. With initial wealth, saving is r a₀ + y₁ − c₁, while next-period assets are a₁ = (1+r)a₀ + y₁ − c₁.`,[{label:'Lifetime budget',color:blue},{label:'Indifference curve',color:green}])}}],
'consumer-worker':[{id:'worker',title:'Work today or work tomorrow?',description:'Let the two wages change separately. Watch leisure, consumption and saving adjust together.',controls:[slider('w1','Current wage w₁',.5,8,.1,2),slider('w2','Future wage w₂',.5,8,.1,2),slider('r','Real interest r',0,30,1,5,'%'),slider('rho','Impatience ρ',0,30,1,5,'%'),slider('eta','Leisure weight η',.2,2,.1,1),slider('h','Time each period',8,24,1,16)],assumptions:'u(c,l)=ln c+η ln l, no initial wealth, free borrowing/lending, terminal wealth zero, 0≤lₜ≤h. The two-period FOCs apply at interior choices.',calculate:p=>{const v=worker(p),cur1=w=>worker({...p,w1:w}).n1,cur2=w=>worker({...p,w2:w}).n1;return output(chart({xmin:.5,xmax:8,ymax:p.h,xlabel:'Changed wage',ylabel:'Current labour N₁',curves:[{fn:cur1,color:green},{fn:cur2,color:purple}],points:[{x:p.w1,y:v.n1,label:'Current wages',color:green}]}),[metric('Current work N₁',f(v.n1)),metric('Future work N₂',f(v.n2)),metric('Saving s₁',f(v.s))],`At your settings c₁ = ${f(v.c1)} and c₂ = ${f(v.c2)}. Raising w₁ changes today’s opportunity cost and lifetime wealth. Raising w₂ changes the relative timing of work and lifetime wealth. In this separable log example a higher future wage reduces current work; a lower future wage increases it. A higher current wage raises current work, subject to the time bounds. The general result depends on preferences, and the tutorial’s income and substitution effects should be identified separately.`,[{label:'Vary w₁, hold w₂',color:green},{label:'Vary w₂, hold w₁',color:purple}])}}],
fiscal:[{id:'ricardo',title:'Tax timing and lifetime resources',description:'Change when taxes are collected while the government’s present-value budget remains balanced.',controls:[slider('G1','Current government G₁',0,40,1,20),slider('G2','Future government G₂',0,40,1,20),slider('T1','Current tax T₁',0,40,1,20),slider('r','Real interest r',0,20,1,5,'%'),select('constrained','Household',[['no','Unconstrained Ricardian'],['yes','Cannot borrow']],'no')],assumptions:'y₁=60, y₂=100, log utility with β=1/1.05, zero initial public debt, lump-sum taxes and known future policy. G is not in household utility.',calculate:p=>{const R=1+p.r/100,T2=p.G2+R*(p.G1-p.T1),v=consumption({y1:60-p.T1,y2:100-T2,a:0,r:p.r,rho:5,constraint:p.constrained}),C=t=>{const tt=p.G2+R*(p.G1-t);return consumption({y1:60-t,y2:100-tt,a:0,r:p.r,rho:5,constraint:p.constrained}).c1};return output(chart({xmax:40,ymax:Math.max(75,v.c1*1.2,C(0)*1.1),xlabel:'Current tax T₁',ylabel:'Current consumption c₁',curves:[{fn:C,color:green}],points:[{x:p.T1,y:v.c1,label:'Chosen timing'}]}),[metric('Required future tax T₂',f(T2)),metric('Current consumption',f(v.c1)),metric('Current public saving T₁−G₁',f(p.T1-p.G1))],`The government budget requires T₂ = G₂ + (1+r)(G₁−T₁) = ${f(T2)}. A tax cut today raises future tax by its accumulated value. ${p.constrained==='yes'?'With a binding borrowing constraint, a tax cut can release current cash and raise consumption. A tax increase can force current consumption down.':'With the Ricardian conditions satisfied, a timing change leaves lifetime resources and consumption unchanged. Private saving rises after a current tax cut, offsetting lower public saving.'} Raising G₁ or G₂ instead reduces household lifetime resources. Tax timing and spending are different experiments.`)}}],
investment:[{id:'capital',title:'How much capital should the firm want?',description:'Compare future marginal product with the user cost of capital.',controls:[slider('A','Future productivity A',.5,3,.1,1.5),slider('r','Real interest r',1,20,.5,5,'%'),slider('d','Depreciation d',0,25,1,10,'%'),slider('pk','Capital price pₖ',.5,3,.1,1),slider('tax','Tax on rental return τ',0,50,5,0,'%'),slider('K1','Current capital K₁',50,400,10,150)],assumptions:'Y₂=A K₂^0.3 N₂^0.7 with N₂=100, common current/future capital price, no adjustment costs. The tax example taxes gross marginal returns with no allowances.',calculate:p=>{const a=.3,N=100,mp=K=>a*p.A*N**.7*K**(-.7)*(1-p.tax/100),uc=(p.r+p.d)/100*p.pk,K=(a*p.A*N**.7*(1-p.tax/100)/uc)**(1/.7),I=K-(1-p.d/100)*p.K1,max=Math.max(400,K*1.4);return output(chart({xmin:Math.min(10,K*.5),xmax:max,ymax:Math.max(uc*2.5,.5),xlabel:'Desired future capital K₂',ylabel:'Return / user cost',curves:[{fn:mp,color:green},{fn:()=>uc,color:orange}],points:[{x:K,y:uc,label:'Desired K₂'}]}),[metric('Desired K₂',f(K)),metric('Gross investment',f(I)),metric('Net investment K₂−K₁',f(K-p.K1))],`User cost is (r+d)pₖ = ${f(uc,3)}. Higher r, depreciation or capital price raises this hurdle and reduces desired K₂. Higher future productivity raises MPK and desired K₂. Lower future productivity reduces it. Gross investment replaces depreciated capital as well as changing the stock. If gross investment is negative here, the frictionless model implies capital disposal; irreversible investment would add a separate constraint.`,[{label:'After-tax future MPK',color:green},{label:'User cost',color:orange}])}},{id:'loanable',title:'Saving and investment equilibrium',description:'Shift saving, investment and government purchases separately.',controls:[slider('s0','Autonomous national saving',10,70,2,40),slider('i0','Autonomous investment',40,100,2,80),slider('G','Extra government purchases',-20,20,1,0)],assumptions:'National saving S = s₀−ΔG+4r and investment I = i₀−6r, with fixed income and fixed taxes. r is measured in percentage points.',calculate:p=>{const r=(p.i0-p.s0+p.G)/10,Q=p.s0-p.G+4*r;return output(chart({xmax:Math.max(110,Q*1.2),ymin:Math.min(-2,r-2),ymax:Math.max(12,r+2),xlabel:'Saving / investment',ylabel:'Real interest rate r (%)',curves:[{fn:q=>(q-p.s0+p.G)/4,color:blue},{fn:q=>(p.i0-q)/6,color:green}],points:[{x:Q,y:r,label:'S = I'}]}),[metric('Equilibrium r',f(r)+'%'),metric('Saving = investment',f(Q)),metric('ΔI from ΔG alone',f(-.6*p.G))],`More autonomous saving shifts S right and lowers r, increasing investment. Less saving raises r and reduces investment. More investment demand raises r and equilibrium saving. At fixed income and taxes, higher G reduces national saving, raising r and crowding out investment in this model. A fall in G releases resources and lowers r.`,[{label:'National saving',color:blue},{label:'Investment',color:green}])}}],
assets:[{id:'money',title:'Money, prices and interest rates',description:'Hold output fixed and separate a short-run rate adjustment from a long-run price adjustment.',controls:[slider('M','Nominal money M',50,200,5,100),slider('P','P in fixed-price mode',.5,2,.05,1),slider('Y','Real income Y',60,180,5,100),slider('pi','Expected inflation πᵉ',-4,10,.5,2,'%'),slider('rbar','Long-run real rate r*',0,8,.5,4,'%'),select('adjustment','Adjustment',[['short','Fixed P → solve rates'],['long','Fixed r* → solve P']],'short')],assumptions:'Real money demand L = 60 + 0.8Y − 10i, i≈r+πᵉ. Quantities and interest rates are illustrative. Negative nominal rates fall outside the non-interest-bearing cash benchmark.',calculate:p=>{if(p.adjustment==='long'){const i=p.rbar+p.pi,L=60+.8*p.Y-10*i,P=L>0?p.M/L:null;return output(chart({xmax:Math.max(220,L*1.2),ymin:Math.min(-8,i-3),ymax:Math.max(15,i+3),xlabel:'Real balances M/P',ylabel:'Nominal interest i (%)',curves:[{fn:q=>(60+.8*p.Y-q)/10,color:green},{fn:()=>i,color:orange}],points:L>0?[{x:L,y:i,label:'Long-run real demand'}]:[]}),[metric('Price level P',P?f(P,3):'No positive solution'),metric('Fixed real rate r*',f(p.rbar)+'%'),metric('Real money demand',f(L))],L>0?`At fixed Y, r* and expected inflation, real money demand is ${f(L)}. Prices adjust to P=M/L=${f(P,3)}. Increasing M raises P proportionally and leaves real balances unchanged. Decreasing M lowers P proportionally. Higher Y raises real money demand and lowers P for a given M. ${i<0?'The selected nominal rate is negative, so this case is outside the strict zero-cash-bound benchmark.':''}`:'The selected rate makes the linear money-demand formula nonpositive. With positive M, no finite positive price level can clear this model. Choose parameters with positive real money demand; extrapolating the linear equation here is invalid.',[{label:'Money demand',color:green},{label:'Long-run nominal rate',color:orange}])}const m=p.M/p.P,i=(60+.8*p.Y-m)/10,r=i-p.pi;return output(chart({xmax:Math.max(220,m*1.2),ymin:Math.min(-8,i-3),ymax:Math.max(15,i+3),xlabel:'Real balances M/P',ylabel:'Nominal interest i (%)',curves:[{fn:q=>(60+.8*p.Y-q)/10,color:green}],lines:[{x1:m,x2:m,y1:Math.min(-8,i-3),y2:Math.max(15,i+3),color:blue}],points:[{x:m,y:i,label:'Asset market'}]}),[metric('Real money balances',f(m)),metric('Nominal rate i',f(i)+'%'),metric('Real rate r ≈ i−πᵉ',f(r)+'%')],`More M or lower P supplies more real balances and lowers the rate needed to clear the asset market at fixed Y. Higher P or less M does the opposite. Higher Y increases transactions demand and raises i at fixed real balances. Expected inflation changes the real rate corresponding to a given nominal opportunity cost. ${i<0?'This unconstrained linear solution has i < 0. With a strict zero nominal bound, a liquidity-trap regime is needed; the line cannot be extrapolated as an ordinary cash equilibrium.':''}`, [{label:'Money demand',color:green},{label:'Real money supply',color:blue}])}},{id:'fisher',title:'Exact Fisher equation',description:'The approximation and the exact purchasing-power calculation are close only for small rates.',controls:[slider('i','Nominal interest i',0,50,1,8,'%'),slider('pi','Inflation π',-10,40,1,5,'%')],assumptions:'Ex-post real return uses realized inflation. Expected inflation gives the corresponding ex-ante relationship when uncertainty is abstracted from.',calculate:p=>{const exact=(1+p.i/100)/(1+p.pi/100)-1,approx=p.i-p.pi;return output(chart({xmin:-10,xmax:40,ymin:-40,ymax:70,xlabel:'Inflation (%)',ylabel:'Real return (%)',curves:[{fn:x=>100*((1+p.i/100)/(1+x/100)-1),color:green},{fn:x=>p.i-x,color:orange,dash:true}],points:[{x:p.pi,y:100*exact,label:'Exact'}]}),[metric('Exact real return',f(100*exact)+'%'),metric('Approximation i−π',f(approx)+'%'),metric('Approximation error',f(approx-100*exact)+' pp')],`One nominal dollar becomes ${f(1+p.i/100,3)} dollars, while the price of the consumption basket multiplies by ${f(1+p.pi/100,3)}. Divide, then subtract one. Higher inflation lowers the real return at fixed i; deflation raises it. A negative real return can coexist with a positive nominal rate.`,[{label:'Exact Fisher',color:green},{label:'First-order approximation',color:orange}])}},{id:'growth',title:'Money growth and inflation',description:'Compare exact proportional changes with the first-order growth formula.',controls:[slider('mu','Money growth μ',-20,60,1,10,'%'),slider('gy','Real income growth',-10,20,1,3,'%'),slider('eta','Income elasticity η',.1,2,.1,1)],assumptions:'L ∝ Y^η, unchanged interest rates and money-demand intercept. Exact P growth = (1+μ)/(1+gY)^η − 1.',calculate:p=>{const exact=100*((1+p.mu/100)/(1+p.gy/100)**p.eta-1),approx=p.mu-p.eta*p.gy;return output(chart({xmin:-20,xmax:60,ymin:Math.min(-40,exact-5),ymax:Math.max(100,exact+5),xlabel:'Money growth (%)',ylabel:'Inflation (%)',curves:[{fn:x=>100*((1+x/100)/(1+p.gy/100)**p.eta-1),color:green},{fn:x=>x-p.eta*p.gy,color:orange,dash:true}],points:[{x:p.mu,y:exact,label:'Exact'}]}),[metric('Exact inflation',f(exact)+'%'),metric('Approximate μ−ηgY',f(approx)+'%'),metric('Exact real money demand growth',f(100*((1+p.gy/100)**p.eta-1))+'%')],`Money growth must accommodate real money-demand growth to keep P stable. Faster money growth raises inflation for the same demand growth; slower money growth lowers inflation and can produce deflation. A fall from 10% to 5% inflation is disinflation with prices still rising. The approximation error grows with the size of finite changes.`,[{label:'Exact growth',color:green},{label:'Approximation',color:orange}])}}],
cycles:[{id:'cycles',title:'Comovement is not causation',description:'Change the timing and sign of a series relative to an illustrative business cycle.',controls:[slider('amp','Amplitude',0,15,1,8),slider('lag','Lag in periods',-4,4,1,0),select('sign','Direction',[['1','Procyclical'],['-1','Countercyclical']],'1'),select('trend','Display',[['gap','Deviation from trend'],['level','Output level with trend']],'gap')],assumptions:'Sine waves are used only to make phase and sign visible. Real business cycles are recurrent, not mechanically periodic. A lagged series need not predict or cause output.',calculate:p=>{const trend=t=>p.trend==='level'?100+2*t:0,Y=t=>trend(t)+8*Math.sin(t*Math.PI/6),X=t=>trend(t)+Number(p.sign)*p.amp*Math.sin((t-p.lag)*Math.PI/6);return output(chart({xmax:24,ymin:p.trend==='level'?80:-18,ymax:p.trend==='level'?165:18,xlabel:'Time',ylabel:p.trend==='level'?'Output / indicator level':'Deviation from trend',curves:[{fn:Y,color:green},{fn:X,color:purple}]}),[metric('Indicator timing',p.lag<0?'Leading':p.lag>0?'Lagging':'Coincident'),metric('Direction',p.sign==='1'?'Procyclical':'Countercyclical'),metric('Amplitude',f(p.amp))],`A negative lag places the indicator’s turning point before output; a positive lag places it after output. Sign describes comovement, while timing describes when movements occur. A fall relative to trend need not mean the level falls. Changing the phase or sign does not establish a causal mechanism. When amplitude is zero, there is no cyclical movement to classify from this synthetic series.`,[{label:'Output',color:green},{label:'Indicator',color:purple}])}}],
islm:[{id:'policy',title:'The original policy lab',description:'The original EC2K2 simulator, incorporated into Decoded. Explore both directions and all adjustment stages.',embed:true},{id:'slopes',title:'LM slope and policy effectiveness',description:'Test ordinary, vertical and liquidity-trap LM regimes.',controls:[slider('a','IS intercept a',10,20,.5,14),slider('M','Money M',60,320,5,100),slider('h','Interest sensitivity h',2,50,2,10),slider('pi','Expected inflation πᵉ',-3,5,.5,0,'%'),select('regime','LM regime',[['ordinary','Ordinary LM'],['vertical','Vertical LM'],['trap','Liquidity trap']],'ordinary')],assumptions:'IS r=a−0.1Y, L=60+0.8Y−h(r+πᵉ), P=1. Vertical LM sets h=0. The trap mode has a strict nominal floor i=0, so r=−πᵉ, but its flat segment applies only when money supply meets transactions demand there. Otherwise it uses the upward segment.',calculate:p=>{p={...p,P:1,k:.8,b:.1,l0:60};const v=policy(p),curves=[{fn:Y=>p.a-.1*Y,color:purple}],lines=[];if(p.regime==='vertical')lines.push({x1:v.Y,x2:v.Y,y1:Math.min(-6,v.r-2),y2:Math.max(16,v.r+2),color:blue});else curves.push({fn:Y=>p.regime==='trap'?Math.max(-p.pi,(60+.8*Y-p.M)/p.h-p.pi):(60+.8*Y-p.M)/p.h-p.pi,color:blue});return output(chart({xmax:Math.max(240,v.Y*1.15),ymin:Math.min(-6,v.r-2),ymax:Math.max(16,v.r+2),xlabel:'Output Y',ylabel:'Real interest r (%)',curves,lines,points:[{x:v.Y,y:v.r,label:'IS = LM'}]}),[metric('Output Y',f(v.Y)),metric('Real interest r',f(v.r)+'%'),metric('Nominal interest i',f(v.i)+'%')],p.regime==='vertical'?'With money demand independent of interest, Y is pinned by real balances. More autonomous spending raises r and crowds out other spending completely at fixed P. More M shifts vertical LM right and raises Y. Less M shifts it left and reduces Y.':p.regime==='trap'?(v.trap?'In the trap, more M is willingly held and does not lower i below the assumed floor, leaving Y unchanged. A higher IS intercept raises Y without raising the rate while the economy remains on the flat segment. The real floor is −πᵉ, not necessarily zero.':`There are too few real balances to reach the flat segment. At i=0, IS would imply Y=${f((p.a+p.pi)/p.b)}, requiring M/P≥${f(v.floorBalances)}. With only ${f(v.m)}, equilibrium remains on the upward-sloping LM segment. Raise M to reach the trap; lowering M from a trap can leave it.`):'A larger h flattens LM, so an IS shift creates more output change and less interest-rate crowding out. Smaller h steepens LM. More M shifts LM down/right; less M shifts it up/left. Higher expected inflation lowers real r for any given nominal opportunity cost.'+(v.i<0?' This unrestricted linear solution has a negative nominal rate. Under a strict cash floor it is infeasible; choose the liquidity-trap regime to enforce that constraint.':''),[{label:'IS',color:purple},{label:'LM',color:blue}])}}],
classical:[{id:'misperceptions',title:'Anticipated or unexpected?',description:'Move nominal demand and expected prices separately to see the source of monetary non-neutrality.',controls:[slider('demand','Nominal demand index D',60,150,5,100),slider('expected','Expected price Pᵉ (manual)',.3,2.5,.05,1),select('expectationMode','Expectations',[['manual','Choose expected price'],['anticipated','Fully anticipated']],'manual'),slider('b','Misperception response b',10,120,10,50),slider('ystar','Potential output Y*',70,130,5,100)],assumptions:'Teaching calibration AD P=D/Y and misperceptions SRAS Y=Y*+b(P−Pᵉ). An anticipated demand change requires setting expected P to D/Y*.',calculate:p=>{if(p.expectationMode==='anticipated')p.expected=p.demand/p.ystar;const a=p.ystar-p.b*p.expected,Y=(a+Math.sqrt(a*a+4*p.b*p.demand))/2,P=p.demand/Y,peStar=p.demand/p.ystar;return output(chart({xmin:Math.max(0,Math.min(50,Y*.75)),xmax:Math.max(170,Y*1.25),ymin:Math.min(.3,P*.8),ymax:Math.max(2.1,P*1.3,p.expected*1.15),xlabel:'Output Y',ylabel:'Price level P',curves:[{fn:Y=>p.demand/Y,color:purple},{fn:Y=>p.expected+(Y-p.ystar)/p.b,color:orange}],lines:[{x1:p.ystar,x2:p.ystar,y1:0,y2:Math.max(2.1,P*1.3,p.expected*1.15),color:green}],points:[{x:Y,y:P,label:'Equilibrium'}]}),[metric('Output Y',f(Y)),metric('Actual P − expected P',f(P-p.expected,3)),metric('Pᵉ for full anticipation',f(peStar,3))],`At these expectations, ${P>p.expected+.001?'prices are higher than expected and firms temporarily produce above Y*.':P<p.expected-.001?'prices are lower than expected and firms produce below Y*.':'the price surprise is zero and output equals Y*.'} If the demand change is fully anticipated, set Pᵉ = ${f(peStar,3)} and Y returns to Y*. An unexpected contraction gives a negative price surprise; an unexpected expansion gives a positive surprise. Rational expectations permits unpredictable errors, not systematic exploitable errors.`,[{label:'AD',color:purple},{label:'Misperceptions SRAS',color:orange},{label:'LRAS',color:green}])}},{id:'rbc',title:'A real productivity shock',description:'Compare a productive shock with a labour-supply wealth effect.',controls:[slider('A','Productivity A',.5,2,.1,1),slider('s','Labour supply scale',50,150,5,100)],assumptions:'Illustrative flexible-price labour market, Y=AK^0.3N^0.7, K=100, supply w=N/s. Increasing s can illustrate the negative wealth effect of higher G on labour supply, without modeling all goods-market responses.',calculate:p=>{const N=(.7*p.A*100**.3*p.s)**(1/1.3),w=N/p.s,Y=p.A*100**.3*N**.7;return output(chart({xmin:Math.min(10,N*.8),xmax:Math.max(170,N*1.2),ymax:Math.max(3,w*1.2),xlabel:'Employment N',ylabel:'Real wage w',curves:[{fn:N=>.7*p.A*100**.3*N**(-.3),color:green},{fn:N=>N/p.s,color:blue}],points:[{x:N,y:w,label:'Flexible-price equilibrium'}]}),[metric('Employment',f(N)),metric('Real wage',f(w)),metric('Potential output',f(Y))],`A favourable productivity shock raises MPN, shifting labour demand right and raising N, w and Y in this calibration. An adverse shock shifts demand left and lowers all three. Increasing labour supply instead raises N and Y while lowering w. This is why the Classical fiscal case can shift FE right while the fixed-FE Keynesian fiscal exercise does not.`,[{label:'Labour demand',color:green},{label:'Labour supply',color:blue}])}}],
keynesian:[{id:'efficiency',title:'The efficiency wage',description:'The firm pays for effort as well as time. See how an effort threshold creates a wage above market clearing.',controls:[slider('b','Effort threshold b',.1,1,.05,.4),slider('A','Labour productivity A',.5,1.5,.1,1),slider('s','Workers willing to supply',50,150,5,100)],assumptions:'Illustrative effort e(w)=√(w−b), w>b. Cost per effort is minimized at w=2b. Labour demand uses a simple reduced-form MPN schedule; this is a mechanism illustration, not an estimated unemployment model.',calculate:p=>{const w=2*p.b,eff=Math.sqrt(w-p.b),Nd=(.7*p.A*100**.3/w)**(1/.3),Ns=p.s*w,emp=Math.min(Nd,Ns),u=Math.max(0,(Ns-Nd)/Ns)*100;return output(chart({xmin:p.b+.02,xmax:Math.max(3,p.b*4),ymax:6,xlabel:'Real wage w',ylabel:'Wage cost per unit effort w/e',curves:[{fn:w=>w/Math.sqrt(w-p.b),color:green}],points:[{x:w,y:w/eff,label:'Minimum cost per effort'}]}),[metric('Efficiency wage',f(w)),metric('Illustrative jobs',f(emp)),metric('Excess supply share',f(u)+'%')],`The cost-minimizing wage is 2b = ${f(w)}. Cutting the wage below this point reduces effort so much that cost per effective unit rises. A higher threshold b raises the preferred wage; a lower threshold lowers it. More willing workers does not automatically induce a wage cut. If demand exceeds supply in this reduced-form illustration, the economy is outside its excess-labour-supply regime and the displayed unemployment is zero.`)}}],
phillips:[{id:'phillips',title:'Inflation, unemployment and expectations',description:'Separate a movement along the curve from an expectations, natural-rate or supply shift.',controls:[slider('pie','Expected inflation πᵉ',-2,10,.5,2,'%'),slider('u','Actual unemployment u',0,12,.5,5,'%'),slider('ustar','Natural rate u*',2,8,.5,5,'%'),slider('h','Slope parameter h',.25,2,.25,1),slider('shock','Supply shock v',-4,4,.5,0,' pp')],assumptions:'Teaching extension π=πᵉ−h(u−u*)+v adds a transient supply term to the lecture equation. The vertical long-run line assumes v returns to zero and expectations are correct. Natural rate is fixed within this experiment. Hysteresis is a separate hypothesis under which persistent unemployment can change u*.',calculate:p=>{const pi=p.pie-p.h*(p.u-p.ustar)+p.shock;return output(chart({xmax:12,ymin:Math.min(-12,pi-4),ymax:Math.max(18,pi+4),xlabel:'Unemployment u (%)',ylabel:'Inflation π (%)',curves:[{fn:u=>p.pie-p.h*(u-p.ustar)+p.shock,color:purple}],lines:[{x1:p.ustar,x2:p.ustar,y1:Math.min(-12,pi-4),y2:Math.max(18,pi+4),color:green}],points:[{x:p.u,y:pi,label:'Current outcome'}]}),[metric('Actual inflation π',f(pi)+'%'),metric('Inflation surprise π−πᵉ',f(pi-p.pie)+' pp'),metric('Unemployment gap',f(p.u-p.ustar)+' pp')],`With expectations and supply conditions fixed, lower u raises π and higher u lowers π. Higher expected inflation shifts the whole short-run curve up; lower expected inflation shifts it down. A positive supply shock v also raises inflation at each u. If v=0 and expectations are correct, u=u*. At π=${f(pi)}%, ${pi<0?'the price level is falling.':'the price level is rising unless inflation is exactly zero.'} Disinflation means π falls over time, which does not require π<0.`,[{label:'Short-run Phillips curve',color:purple},{label:'Natural-rate long run',color:green}])}},{id:'hysteresis',title:'A temporary gap, a lasting scar?',description:'Compare a fixed natural rate with an illustrative adjustment of the natural rate toward unemployment.',controls:[slider('gap','Initial unemployment gap',-3,6,.5,3,' pp'),slider('duration','Shock duration',1,8,1,3),slider('lambda','Persistence λ',0,.5,.05,0)],assumptions:'Illustrative dynamics only, u*ₜ₊₁=u*ₜ+λ(uₜ−u*ₜ), initial u*=5. Actual unemployment stays at 5+gap during the shock, then equals the new natural rate. λ is not a course estimate.',calculate:p=>{let natural=5,arr=[];for(let t=0;t<=12;t++){const u=t<p.duration?5+p.gap:natural;arr.push({u,natural});natural+=p.lambda*(u-natural)}const at=(t,k)=>arr[Math.min(12,Math.max(0,Math.round(t)))][k];return output(chart({xmax:12,ymax:12,xlabel:'Time',ylabel:'Unemployment (%)',curves:[{fn:t=>at(t,'u'),color:purple},{fn:t=>at(t,'natural'),color:green}]}),[metric('Starting natural rate','5%'),metric('Ending natural rate',f(arr[12].natural)+'%'),metric('Lasting change',f(arr[12].natural-5)+' pp')],`At λ=0, a temporary disturbance leaves u* unchanged. At λ>0, prolonged unemployment above u* raises the natural rate in this illustrative rule, consistent with mechanisms such as skill loss and insider–outsider effects. A negative gap lowers it under this symmetric illustration, although the lecture does not establish symmetric empirical effects. Hysteresis challenges an automatic return to the original natural rate.`,[{label:'Actual unemployment',color:purple},{label:'Natural rate',color:green}])}}]
};
export function mountLab(container,lesson){const labs=LABS[lesson]||[],state={};let selected=labs[0];if(!selected){container.innerHTML='';return}const drawShell=()=>{container.innerHTML=`<div class="lab-head"><div><p class="eyebrow">CHANGE SOMETHING. EXPLAIN WHAT FOLLOWS.</p><h2>Interactive experiments</h2></div>${labs.length>1?`<select aria-label="Choose experiment" id="lab-select">${labs.map(l=>`<option value="${l.id}" ${l===selected?'selected':''}>${E(l.title)}</option>`).join('')}</select>`:''}</div><h3>${E(selected.title)}</h3><p class="small">${E(selected.description)}</p><div id="lab-inner"></div>`;container.querySelector('#lab-select')?.addEventListener('change',e=>{selected=labs.find(l=>l.id===e.target.value);drawShell()});const inner=container.querySelector('#lab-inner');if(selected.embed){inner.innerHTML='<iframe class="policy-embed" title="Integrated IS–LM–FE and AD–AS policy simulator" src="policy/index.html'+E(location.search)+'#lab" loading="lazy"></iframe>';return}const p=state[selected.id]||(state[selected.id]=Object.fromEntries(selected.controls.map(c=>[c.id,c.value])));inner.innerHTML=`<div class="lab-layout"><div class="lab-controls">${selected.controls.map(c=>c.options?`<label class="select-label">${E(c.label)}<select data-control="${c.id}">${c.options.map(([v,t])=>`<option value="${v}" ${p[c.id]==v?'selected':''}>${E(t)}</option>`).join('')}</select></label>`:`<div class="slider-control"><label for="control-${c.id}">${E(c.label)}<output id="value-${c.id}">${f(p[c.id])}${E(c.unit)}</output></label><input id="control-${c.id}" data-control="${c.id}" type="range" min="${c.min}" max="${c.max}" step="${c.step}" value="${p[c.id]}"></div>`).join('')}<button class="secondary" id="lab-reset">Reset experiment ↺</button></div><div><div class="lab-legend" id="lab-legend"></div><div class="lab-chart" id="lab-chart"></div><div class="lab-values" id="lab-values"></div></div></div><div class="lab-explanation" id="lab-explanation" aria-live="polite"></div><p class="lab-assumptions">${E(selected.assumptions)}</p>`;const update=()=>{const o=selected.calculate({...p});inner.querySelector('#lab-chart').innerHTML=o.graph;inner.querySelector('#lab-values').innerHTML=o.values.map(v=>`<div><strong>${E(v.value)}</strong><span>${E(v.label)}</span></div>`).join('');inner.querySelector('#lab-legend').innerHTML=o.legend.map(l=>`<span><i style="background:${l.color}"></i>${E(l.label)}</span>`).join('');inner.querySelector('#lab-explanation').textContent=o.explain};inner.querySelectorAll('[data-control]').forEach(el=>el.addEventListener('input',()=>{const c=selected.controls.find(c=>c.id===el.dataset.control);p[c.id]=c.options?el.value:Number(el.value);if(!c.options)inner.querySelector('#value-'+c.id).textContent=f(p[c.id])+c.unit;update()}));inner.querySelector('#lab-reset').onclick=()=>{delete state[selected.id];drawShell()};update()};drawShell()}
